"""Request metadata helpers for lightweight API handlers."""

from dataclasses import dataclass, field
from uuid import uuid4


CORRELATION_HEADER = "X-Correlation-ID"


@dataclass
class RequestContext:
    method: str
    path: str
    headers: dict[str, str] = field(default_factory=dict)

    def correlation_id(self) -> str:
        for key, value in self.headers.items():
            if key.lower() == CORRELATION_HEADER.lower() and value.strip():
                return value.strip()
        return f"req-{uuid4().hex[:12]}"


def context_from_environ(environ: dict) -> RequestContext:
    headers: dict[str, str] = {}
    for key, value in environ.items():
        if key.startswith("HTTP_"):
            header = key[5:].replace("_", "-").title()
            headers[header] = str(value)
    return RequestContext(
        method=str(environ.get("REQUEST_METHOD", "GET")),
        path=str(environ.get("PATH_INFO", "/")),
        headers=headers,
    )


def lower_headers(headers: dict[str, str]) -> dict[str, str]:
    return {key.lower(): value for key, value in headers.items()}

# Operational helpers used by this challenge domain.
REQUEST_CONTEXT_DOMAIN_TERMS = ('correlation', 'request', 'header', 'response')

class RequestContextLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def request_context_compact_metadata(metadata):
    """Return public correlation metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def request_context_merge_context(base, extra):
    """Merge request context without mutating caller-owned dictionaries."""
    merged = request_context_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def request_context_labels(records, key="name"):
    """Extract labels for header diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def request_context_group_by_status(records, key="status"):
    """Group response records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def request_context_summary(records, key="status"):
    """Count request context records by status."""
    return {name: len(items) for name, items in request_context_group_by_status(records, key).items()}

